/**
 * AppShell.NavItem: a row of the rail, start-aligned, a link or a button.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/app-shell.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, useContext, type JSX } from 'solid-js'

import {
  Icon,
  claimSlot,
  createDerived,
  ownerContext,
  resolveSlot,
  scope,
  type Defaults,
  type IconRole,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/archetypes/app-shell.module.css'
import Tooltip from '../overlays/Tooltip'
import type { AppShellOwner } from './AppShell'

export interface AppShellNavItemProps {
  /**
   * Expected in practice, because a collapsed rail is unusable without icons.
   */
  icon?: IconRole
  /**
   * The accessible name in every mode, including collapsed.
   */
  label: string
  /**
   * Marks the current page, with exactly one per rail.
   */
  current?: boolean
  /**
   * With an `href`, the row is an `<a>` with Link's semantics and NavItem's styling.
   */
  href?: string
  /**
   * The app's router, on a row with an `href`: a click that would navigate this tab calls it in
   * place of the browser.
   */
  onNavigate?: (href: string) => void
  /**
   * For a rail of buttons that routes in script with no `href`; it also fires on every click of
   * a row with one.
   */
  onSelect?: () => void
  /**
   * Trailing content, by convention a Badge with a count.
   */
  end?: JSX.Element
}

/** AppShell.NavItem: a row of the rail, start-aligned, a link or a button. */
export default function AppShellNavItem(given: AppShellNavItemProps): JSX.Element {
  const props = mergeProps(
    { current: false } as Defaults<AppShellNavItemProps, 'current'>,
    claimSlot(given),
  )
  const owner = useContext(ownerContext<AppShellOwner>('AppShell')) ?? ({} as AppShellOwner)
  return scope(() => {
    const endSlot = resolveSlot(() => props.end)
    const navigatesHere = createDerived(
      () =>
        (event: MouseEvent): boolean =>
          !event.defaultPrevented &&
          event.button === 0 &&
          !event.metaKey &&
          !event.ctrlKey &&
          !event.shiftKey &&
          !event.altKey,
    )
    const route = createDerived(() => (event: MouseEvent): void => {
      if (
        props.href === undefined ||
        !(props.onNavigate !== undefined) ||
        !navigatesHere.value(event)
      )
        return
      event.preventDefault()
      props.onNavigate?.(props.href)
    })
    return (
      <>
        {owner.collapsed === true ? (
          <Tooltip content={props.label} side="right">
            {props.href === undefined ? (
              <button
                class={styles.navItem}
                type="button"
                aria-current={props.current ? 'page' : undefined}
                data-current={props.current ? '' : undefined}
                onclick={() => props.onSelect?.()}
              >
                {props.icon !== undefined ? (
                  <span class={styles.navGlyph}>
                    <Icon name={props.icon} />
                  </span>
                ) : null}
                {/* label */}
                <span class={styles.navLabel}>{props.label}</span>
                {endSlot.filled() ? <span class={styles.navEnd}>{endSlot()}</span> : null}
              </button>
            ) : (
              <a
                class={styles.navItem}
                href={props.href}
                aria-current={props.current ? 'page' : undefined}
                data-current={props.current ? '' : undefined}
                onclick={($event: MouseEvent) => (props.onSelect?.(), route.value($event))}
              >
                {props.icon !== undefined ? (
                  <span class={styles.navGlyph}>
                    <Icon name={props.icon} />
                  </span>
                ) : null}
                {/* label */}
                <span class={styles.navLabel}>{props.label}</span>
                {endSlot.filled() ? <span class={styles.navEnd}>{endSlot()}</span> : null}
              </a>
            )}
          </Tooltip>
        ) : props.href === undefined ? (
          <button
            class={styles.navItem}
            type="button"
            aria-current={props.current ? 'page' : undefined}
            data-current={props.current ? '' : undefined}
            onclick={() => props.onSelect?.()}
          >
            {props.icon !== undefined ? (
              <span class={styles.navGlyph}>
                <Icon name={props.icon} />
              </span>
            ) : null}
            {/* label */}
            <span class={styles.navLabel}>{props.label}</span>
            {endSlot.filled() ? <span class={styles.navEnd}>{endSlot()}</span> : null}
          </button>
        ) : (
          <a
            class={styles.navItem}
            href={props.href}
            aria-current={props.current ? 'page' : undefined}
            data-current={props.current ? '' : undefined}
            onclick={($event: MouseEvent) => (props.onSelect?.(), route.value($event))}
          >
            {props.icon !== undefined ? (
              <span class={styles.navGlyph}>
                <Icon name={props.icon} />
              </span>
            ) : null}
            {/* label */}
            <span class={styles.navLabel}>{props.label}</span>
            {endSlot.filled() ? <span class={styles.navEnd}>{endSlot()}</span> : null}
          </a>
        )}
      </>
    )
  })
}
